아래는 Go 언어로 `net/http` 패키지만 사용하여 간단한 TODO REST API를 만든 코드입니다. 이 코드는 `GET /todos`, `POST /todos`, `DELETE /todos/{id}` 엔드포인트를 지원하며 JSON 형식으로 응답합니다.

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"sync"
)

type Todo struct {
	ID   int    `json:"id"`
	Text string `json:"text"`
}

var (
	todos    = make(map[int]Todo)
	nextID   = 1
	todoLock sync.Mutex
)

func main() {
	http.HandleFunc("/todos", getTodos)
	http.HandleFunc("/todos/", handleTodo)

	log.Println("Server started on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func getTodos(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	todoLock.Lock()
	defer todoLock.Unlock()

	todoSlice := make([]Todo, 0, len(todos))
	for _, todo := range todos {
		todoSlice = append(todoSlice, todo)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todoSlice)
}

func handleTodo(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Path[len("/todos/"):])
	if err != nil {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}

	todoLock.Lock()
	defer todoLock.Unlock()

	switch r.Method {
	case http.MethodPost:
		var todo Todo
		if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
			http.Error(w, "Invalid request payload", http.StatusBadRequest)
			return
		}
		todo.ID = nextID
		nextID++
		todos[todo.ID] = todo
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(todo)
	case http.MethodDelete:
		if _, exists := todos[id]; !exists {
			http.Error(w, "Todo not found", http.StatusNotFound)
			return
		}
		delete(todos, id)
		w.WriteHeader(http.StatusNoContent)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}
```

이 코드는 다음과 같은 기능을 제공합니다:

1. `GET /todos`: 모든 TODO 항목을 JSON 배열로 반환합니다.
2. `POST /todos`: 새로운 TODO 항목을 추가합니다. 요청 본문은 JSON 형식이어야 합니다.
3. `DELETE /todos/{id}`: 지정된 ID의 TODO 항목을 삭제합니다.

서버는 `:8080` 포트에서 실행됩니다. 각 요청이 공유 자원인 `todos` 맵에 접근할 수 있도록 `sync.Mutex`를 사용하여 락을 걸었습니다.

아래는 Go 언어로 HTTP 미들웨어 체인을 구현한 코드입니다. 로깅 미들웨어, 인증 미들웨어, CORS 미들웨어를 만들고 체이닝할 수 있게 작성했습니다.

```go
package main

import (
	"log"
	"net/http"
	"strings"

	"github.com/dgrijalva/jwt-go"
)

type Middleware func(http.Handler) http.Handler

func LoggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		log.Printf("Started %s %s", r.Method, r.URL.Path)
		next.ServeHTTP(w, r)
		log.Printf("Completed %s %s", r.Method, r.URL.Path)
	})
}

func AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}

		tokenString := strings.Replace(authHeader, "Bearer ", "", 1)
		_, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {
			return []byte("secret_key"), nil
		})

		if err != nil {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}

		next.ServeHTTP(w, r)
	})
}

func CORSMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")

		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}

		next.ServeHTTP(w, r)
	})
}

func ChainMiddleware(middlewares ...Middleware) Middleware {
	return func(next http.Handler) http.Handler {
		for _, m := range middlewares {
			next = m(next)
		}
		return next
	}
}

func helloHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("Hello, World!"))
}

func main() {
	middlewareChain := ChainMiddleware(LoggingMiddleware, AuthMiddleware, CORSMiddleware)
	handler := middlewareChain(http.HandlerFunc(helloHandler))

	log.Println("Server is running on :8080")
	http.ListenAndServe(":8080", handler)
}
```

이 코드는 로깅 미들웨어, 인증 미들웨어, CORS 미들웨어를 만들고 이를 체이닝하여 사용할 수 있게 구현했습니다. `ChainMiddleware` 함수를 사용하여 미들웨어들을 체인으로 연결할 수 있습니다. 그리고 마지막으로 `helloHandler` 함수를 사용하여 간단한 HTTP 핸들러를 구현했습니다.

