from abc import ABC, abstractmethod

class PaymentStrategy(ABC):
    @abstractmethod
    def pay(self, amount: float) -> None:
        pass

class CreditCard(PaymentStrategy):
    def pay(self, amount: float) -> None:
        print(f"Paying {amount} using Credit Card.")

class PayPal(PaymentStrategy):
    def pay(self, amount: float) -> None:
        print(f"Paying {amount} using PayPal.")

class Bitcoin(PaymentStrategy):
    def pay(self, amount: float) -> None:
        print(f"Paying {amount} using Bitcoin.")

class PaymentContext:
    def __init__(self, strategy: PaymentStrategy):
        self._strategy = strategy

    def set_strategy(self, strategy: PaymentStrategy) -> None:
        self._strategy = strategy

    def pay(self, amount: float) -> None:
        self._strategy.pay(amount)

# Example usage
if __name__ == "__main__":
    payment_context = PaymentContext(CreditCard())
    payment_context.pay(100.0)

    payment_context.set_strategy(PayPal())
    payment_context.pay(200.0)

    payment_context.set_strategy(Bitcoin())
    payment_context.pay(300.0)
