package main

import (
	"fmt"
	"math"
)

type Shape interface {
	Area() float64
	Perimeter() float64
}

type Circle struct {
	Radius float64
}

func (c *Circle) Area() float64 {
	return math.Pi * c.Radius * c.Radius
}

func (c *Circle) Perimeter() float64 {
	return 2 * math.Pi * c.Radius
}

type Rectangle struct {
	Width  float64
	Height float64
}

func (r *Rectangle) Area() float64 {
	return r.Width * r.Height
}

func (r *Rectangle) Perimeter() float64 {
	return 2 * (r.Width + r.Height)
}

type Triangle struct {
	SideA float64
	SideB float64
	SideC float64
}

func (t *Triangle) Area() float64 {
	// Heron's formula
	s := (t.SideA + t.SideB + t.SideC) / 2
	return math.Sqrt(s * (s - t.SideA) * (s - t.SideB) * (s - t.SideC))
}

func (t *Triangle) Perimeter() float64 {
	return t.SideA + t.SideB + t.SideC
}

func NewShape(shapeType string, dimensions ...float64) Shape {
	switch shapeType {
	case "circle":
		if len(dimensions) == 1 {
			return &Circle{Radius: dimensions[0]}
		}
	case "rectangle":
		if len(dimensions) == 2 {
			return &Rectangle{Width: dimensions[0], Height: dimensions[1]}
		}
	case "triangle":
		if len(dimensions) == 3 {
			return &Triangle{SideA: dimensions[0], SideB: dimensions[1], SideC: dimensions[2]}
		}
	}
	return nil
}

func main() {
	circle := NewShape("circle", 5)
	rectangle := NewShape("rectangle", 4, 6)
	triangle := NewShape("triangle", 3, 4, 5)

	fmt.Printf("Circle - Area: %.2f, Perimeter: %.2f\n", circle.Area(), circle.Perimeter())
	fmt.Printf("Rectangle - Area: %.2f, Perimeter: %.2f\n", rectangle.Area(), rectangle.Perimeter())
	fmt.Printf("Triangle - Area: %.2f, Perimeter: %.2f\n", triangle.Area(), triangle.Perimeter())
}
